\documentclass[11pt]{article}
\usepackage{amsmath}

\title{Shear Design of a Reinforced Concrete Beam with Recycled Coarse Aggregate}
\author{CIVE 542 Design Report --- Group 7}
\date{June 2026}

\begin{document}
\maketitle

\section{Design Basis}
The beam is simply supported over a clear span of 5.4~m and carries a
factored uniformly distributed load of 42~kN/m including self-weight.
The concrete mixture replaces 30\% of the natural coarse aggregate
with recycled concrete aggregate of saturated surface-dry density
2{,}410~kg/m$^3$.

\section{Section Properties}
The effective depth is $d = 512$~mm, the web width is $b_w = 250$~mm,
and the specified cylinder strength is $f'_c = 32$~MPa. The concrete
shear resistance follows
\begin{equation}
V_c = 0.17 \, \lambda \sqrt{f'_c} \, b_w d,
\end{equation}
with $\lambda = 0.85$ accounting for the lower density of the recycled
aggregate mixture.

\section{Stirrup Design}
The required stirrup spacing is governed by the following checks:
\begin{itemize}
\item shear demand at the critical section located $d$ from the support face;
\item maximum spacing limit for moderate shear, $s \le d/2$;
\item minimum shear reinforcement ratio $\rho_{w,\min} = 0.08 \sqrt{f'_c} / f_y$.

\section{Detailing}
Closed stirrups with 135-degree hooks are used throughout the shear
span, and the first stirrup is placed at $s/2$ from the support face.
The longitudinal bars are anchored at the supports with standard hooks,
and the development length is checked against the code expression for
recycled aggregate concrete.

\section{Conclusion}
The section satisfies the shear demand with two-legged 10~mm stirrups
at 200~mm spacing in the end regions and 250~mm spacing at midspan.

\end{document}

